/* Light: Neutral and quiet: the reference look. */
[data-example-theme="light"] {
    --floor: rgb(255, 255, 255);
    --ink: rgb(20, 20, 20);
}

/* Dark: The reference look, at night. */
[data-example-theme="dark"] {
    --floor: rgb(17, 24, 39);
    --ink: rgb(240, 240, 240);
}

/* Paper: Warm and wide: rounded tabs, generous splitters. */
[data-example-theme="paper"] {
    --floor: rgb(245, 239, 224);
    --ink: rgb(60, 40, 20);
}

/* Terminal: Green on black, monospace, square. */
[data-example-theme="terminal"] {
    --floor: rgb(0, 26, 0);
    --ink: rgb(120, 255, 120);
}
